import React, { useState, useEffect } from "react";
import api from "../../api";

const Artikel = () => {
  const [loading, setLoading] = useState(false);
  const [data, setData] = useState([]);

  useEffect(() => {
    setLoading(true);
    // Simulasi fetch data artikel
    setTimeout(() => {
        api.get('/keuangan')
        .then(response => {
          setData(response.data);
        })
