  return (
    <div className="grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
      {loading ? (
        <div className="col-span-3 text-center text-gray-500">Loading...</div>
      ) : data.length > 0 ? (
        <table className="min-w-full bg-white border border-teal-300 rounded-lg shadow">
          <thead className="bg-teal-700 text-white">
            <tr>
              <th className="px-6 py-3 text-left font-medium">No</th>
              <th className="px-6 py-3 text-left font-medium">Judul</th>
              <th className="px-6 py-3 text-left font-medium">Deskripsi</th>
              <th className="px-6 py-3 text-left font-medium">Action</th>
            </tr>
          </thead>
          <tbody>
            {data.map((row, index) => (
              <tr key={row.id}>
                <td className="px-6 py-4">{index + 1}</td>
                <td className="px-6 py-4">{row.judul}</td>
                <td className="px-6 py-4">{row.deskripsi}</td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <div className="col-span-3 text-center text-gray-500">
          Tidak ada data untuk artikel.
        </div>
      )}
    </div>
  );
};

export default Artikel;
